using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioThreeEdgeCornerValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static int cases,flows;static string phase;static SceneView view;
 static object Get(object o,string n)=>o.GetType().GetField(n,F).GetValue(o);static void Check(bool b,string m){if(!b)throw new Exception(phase+": "+m);}
 static StudioModelDocument.Node Make(Vector3 sign,int transform,float width,int sub,bool verify,bool reverse=false){phase=$"corner={sign} transform={transform} width={width} sub={sub}";var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);var original=mesh.vertices;Vector3 Map(Vector3 p)=>transform==0?p:transform==1?new Vector3(p.x+.25f*p.y,p.y*1.2f,p.z*1.7f):Quaternion.Euler(17,29,-11)*Vector3.Scale(p,new Vector3(1.1f,1.6f,.8f));var corner=sign*.5f;var selected=new List<(int,int)>();var seen=new HashSet<(Vector3,Vector3)>();var node=new StudioModelDocument.Node{mesh=mesh,cutPolygons=polygons,cutTriangles=mesh.triangles};var source=new StudioMeshCuts(node);foreach(var face in source.Faces)for(int k=0;k<face.Vertices.Count;k++){int a=face.Vertices[k],b=face.Vertices[(k+1)%face.Vertices.Count];if(source.Positions[a]!=corner&&source.Positions[b]!=corner)continue;if(seen.Add(StudioMeshCuts.NormalEdgePositionKeyForBevel(source.Positions[a],source.Positions[b])))selected.Add((a,b));}if(reverse)selected.Reverse();mesh.vertices=original.Select(Map).ToArray();mesh.RecalculateBounds();source=new StudioMeshCuts(node);source.BevelEdges(node,selected,new StudioMeshCuts.BevelOptions{Width=width,Subdivisions=sub,Tension=1});if(!verify)return node;var result=new StudioMeshCuts(node);var uses=new Dictionary<(Vector3,Vector3),int>();var neighbors=new Dictionary<Vector3,HashSet<Vector3>>();double volume=0;foreach(var face in result.Faces){for(int k=0;k<face.Vertices.Count;k++){var a=result.Positions[face.Vertices[k]];var b=result.Positions[face.Vertices[(k+1)%face.Vertices.Count]];Check((a-b).sqrMagnitude>1e-12,"Collapsed authored edge");var key=StudioMeshCuts.NormalEdgePositionKeyForBevel(a,b);uses.TryGetValue(key,out int n);uses[key]=n+1;if(!neighbors.TryGetValue(a,out var list))neighbors[a]=list=new HashSet<Vector3>();list.Add(b);if(!neighbors.TryGetValue(b,out list))neighbors[b]=list=new HashSet<Vector3>();list.Add(a);}var p=result.Positions[face.Vertices[0]];for(int k=1;k+1<face.Vertices.Count;k++)volume+=Vector3.Dot(p,Vector3.Cross(result.Positions[face.Vertices[k]],result.Positions[face.Vertices[k+1]]))/6d;}Check(uses.Values.All(n=>n==2),"Open or nonmanifold corner "+string.Join(";",uses.Where(p=>p.Value!=2).Select(p=>p.Key+" uses="+p.Value)));Check(volume>0,"Inverted volume");Check(neighbors.Count-uses.Count+result.Faces.Count==2,"Corner Euler characteristic");if(sub==0){Check(result.Faces.Count==10&&result.Faces.Count(f=>f.Vertices.Count==3)==1,"Flat corner must be three strips and one triangle");}else{var draft=Get(source,"reusableBevelDraft");var positions=(List<Vector3>)Get(draft,"Positions");var owners=(List<int>)Get(draft,"Owners");var anchors=(HashSet<int>)Get(draft,"JunctionAnchors");var directions=(Dictionary<(int,int),Vector3>)Get(draft,"JunctionFlow");var target=Map(corner);var originals=(Vector3[])Get(draft,"Originals");var done=new HashSet<int>();foreach(var pair in directions)foreach(int id in new[]{pair.Key.Item1,pair.Key.Item2}){if(anchors.Contains(id)||!done.Add(id)||Vector3.Distance(originals[owners[id]],target)>1e-5||!neighbors.TryGetValue(positions[id],out var adjacent))continue;var direction=pair.Value.normalized;if(transform!=1)Check(adjacent.Any(p=>{var d=(p-positions[id]).normalized;return Vector3.Dot(d,direction)>.9999f;}),"Corner row kinks from incoming strip: sub="+sub+" transform="+transform+" point="+positions[id]);if(transform!=1)flows++;}Check(done.Count>0,"No rounded-profile flow samples");}cases++;Object.DestroyImmediate(mesh);return null;}
 public static void Run(){EditorApplication.delayCall+=()=>{try{for(int c=0;c<8;c++)foreach(int transform in new[]{0,1,2})foreach(float width in new[]{.04f,.12f,.2f})foreach(int sub in new[]{0,1,3,8})foreach(bool reverse in new[]{false,true})Make(new Vector3((c&1)==0?-1:1,(c&2)==0?-1:1,(c&4)==0?-1:1),transform,width,sub,true,reverse);view=ScriptableObject.CreateInstance<SceneView>();view.position=new Rect(100,100,650,650);view.Show();SceneView.duringSceneGui+=Draw;view.Repaint();}catch(Exception e){Finish(e.ToString());}};}
 static void Draw(SceneView scene){if(scene!=view||Event.current.type!=EventType.Repaint)return;SceneView.duringSceneGui-=Draw;string report;try{foreach(int sub in new[]{0,3}){var node=Make(Vector3.one,0,.15f,sub,false);var doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(node);using(var ed=new StudioModelEditor(()=>{})){ed.Load(doc);ed.SelectObject(0);ed.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Face);var rt=new RenderTexture(600,600,24);rt.Create();var old=RenderTexture.active;var target=view.camera.targetTexture;var rect=view.camera.pixelRect;var material=new Material(Shader.Find("Hidden/StudioValidationSolid"));GL.PushMatrix();try{view.camera.targetTexture=rt;view.camera.pixelRect=new Rect(0,0,600,600);view.camera.transform.position=Vector3.one*1.6f;view.camera.transform.rotation=Quaternion.LookRotation(-Vector3.one);view.camera.fieldOfView=30;view.camera.nearClipPlane=.03f;view.camera.farClipPlane=100;Handles.SetCamera(new Rect(0,0,600,600),view.camera);RenderTexture.active=rt;GL.Viewport(new Rect(0,0,600,600));GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;material.SetPass(0);Graphics.DrawMeshNow(node.mesh,Matrix4x4.identity);typeof(StudioModelEditor).GetMethod("DrawVisibleObjectWireframes",F).Invoke(ed,new object[]{view.camera});var t=new Texture2D(600,600,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,600,600),0,0);t.Apply();Check(t.GetPixels32().Count(p=>p.g>p.r*1.2f&&p.b>p.r*1.1f)>100,"Missing rendered bevel boundaries");File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../three-edge-corner-"+sub+".png")),t.EncodeToPNG());Object.DestroyImmediate(t);}finally{view.camera.targetTexture=target;view.camera.pixelRect=rect;Handles.SetCamera(view.camera);GL.PopMatrix();RenderTexture.active=old;Object.DestroyImmediate(rt);Object.DestroyImmediate(material);}}Object.DestroyImmediate(node.mesh);Object.DestroyImmediate(doc);}report="PASS "+cases+" cube-corner topology cases; "+flows+" tangent-aligned profile row samples; native flat/rounded wire render captures";}catch(Exception e){report=e.ToString();}Finish(report);}
 static void Finish(string r){File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../three-edge-corner-result.txt")),r);EditorApplication.delayCall+=()=>{if(view)view.Close();EditorApplication.Exit(r.StartsWith("PASS")?0:1);};}
}


